const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const id = String($json.messageId || '');
if (!id) return [];
if (staticData.seen[id]) return [];
staticData.seen[id] = Date.now();
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
for (const k of Object.keys(staticData.seen)) {
  if (staticData.seen[k] < cutoff) delete staticData.seen[k];
}
return [$json];

