const raw = $json.choices?.[0]?.message?.content || '{}';
let c;
try { c = JSON.parse(raw); } catch { return []; }
const priority = String(c.priority || 'low').toLowerCase();
const hasDeadline = Boolean(c.has_deadline);
if (priority !== 'high' && !hasDeadline) return [];
const line = String(c.alert_line || c.whatsapp_line || '').slice(0, 200);
return [{
  json: {
    ...c,
    priority,
    has_deadline: hasDeadline,
    alert_line: line,
    from: $('Normalize Mail').item.json.from,
    subject: $('Normalize Mail').item.json.subject,
    messageId: $('Normalize Mail').item.json.messageId
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.hourly = staticData.hourly || [];
const now = Date.now();
staticData.hourly = staticData.hourly.filter((t) => now - t < 3600 * 1000);
if (staticData.hourly.length >= 6) return [];
staticData.hourly.push(now);
return [$json];
